"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3306],{89928:e=>{e.exports=JSON.parse('{"functions":[{"name":"build","desc":"Advances every in-flight build job. Runs in `Phases.Update`, ahead of `load`.\\n\\nFinishing work already started outranks starting more. A half-built chunk is\\nalready paying for its residency without being useful, so the frame\'s\\nallowance goes to completing it before any new chunk is generated.\\n\\nUnlike the other maze systems this ignores `resyncNeeded` \u2014 a build backlog\\nhas to keep draining whether or not anyone is moving.","params":[{"name":"world","desc":"","lua_type":"jecs.World"}],"returns":[{"desc":"Update function.","lua_type":"() -> ()"},{"desc":"Cleanup function.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":33,"path":"src/main/server/systems/maze/build.luau"}}],"properties":[],"types":[],"name":"build","desc":"Spends the per-frame build budget turning queued chunk data into instances.","tags":["server-system"],"realm":["Server"],"source":{"line":8,"path":"src/main/server/systems/maze/build.luau"}}')}}]);